SELECT 'core-2026-09-v4','demonstratives','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"demonstratives","title":"This, that, these and those","level":"A1","order":5,"summary":"Choose words that point to things and distinguish number from distance.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Near and far","Plural demonstratives","Pointing without a following noun","Referring to ideas and time"],"rules":[{"title":"Near and far","explanation":"Use **this** for one nearby thing and **that** for one more distant thing. Distance can be physical or part of how the speaker views a situation. Demonstratives can stand alone or come before a noun.","pattern":"**This** seat is free. / **That** seat by the door is taken.","commonMistakes":["This and that are singular, even when the object seems large or contains many parts."],"examples":["Point to one book in your hand: “**This** book is mine.”","Point to one box in your hand: “**This** box is mine.”"],"skill":"form"},{"title":"Plural demonstratives","explanation":"Use **these** for nearby plural things and **those** for more distant plural things. Match the following noun and verb to plural number. Near and far are described explicitly in the practice so that the intended choice is clear.","pattern":"**These books are** mine. / **Those books are** yours.","commonMistakes":["These is pronounced differently from this. In writing, remember the final -e in these."],"examples":["Point to one book far away across the room: “**That** book is yours.”","Point to one box far away across the room: “**That** box is yours.”"],"skill":"meaning"},{"title":"Pointing without a following noun","explanation":"A demonstrative can function as a pronoun when the thing is already understood. It still has number: This is mine; These are mine. Do not add an unnecessary noun merely because the demonstrative has no following noun.","pattern":"What is **that**? / Who owns **these**?","commonMistakes":["The word it refers back to an identified thing but does not make the same near/far contrast."],"examples":["Point to several books beside you: “**These** books are ours.”","Point to several boxes beside you: “**These** boxes are ours.”"],"skill":"contrast"},{"title":"Referring to ideas and time","explanation":"This and that can refer to an event or whole idea. This week identifies the current week; that week points to a week already identified elsewhere. In conversation, that often responds to something just said.","pattern":"The train was cancelled. **That** was frustrating.","commonMistakes":["Real conversational choices depend on viewpoint. The questions here use explicit physical distance rather than judging subjective emphasis."],"examples":["Point to several books far away beyond the fence: “**Those** books are theirs.”","Point to several boxes far away beyond the fence: “**Those** boxes are theirs.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Choose words that point to things and distinguish number from distance.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Near and far","explanation":"Use **this** for one nearby thing and **that** for one more distant thing. Distance can be physical or part of how the speaker views a situation. Demonstratives can stand alone or come before a noun.","pattern":"**This** seat is free. / **That** seat by the door is taken.","commonMistakes":["This and that are singular, even when the object seems large or contains many parts."],"examples":["Point to one book in your hand: “**This** book is mine.”","Point to one box in your hand: “**This** box is mine.”"],"skill":"form","id":"demonstratives-foundation-1","domain":"reference","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"title":"Plural demonstratives","explanation":"Use **these** for nearby plural things and **those** for more distant plural things. Match the following noun and verb to plural number. Near and far are described explicitly in the practice so that the intended choice is clear.","pattern":"**These books are** mine. / **Those books are** yours.","commonMistakes":["These is pronounced differently from this. In writing, remember the final -e in these."],"examples":["Point to one book far away across the room: “**That** book is yours.”","Point to one box far away across the room: “**That** box is yours.”"],"skill":"meaning","id":"demonstratives-foundation-2","domain":"reference","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"title":"Pointing without a following noun","explanation":"A demonstrative can function as a pronoun when the thing is already understood. It still has number: This is mine; These are mine. Do not add an unnecessary noun merely because the demonstrative has no following noun.","pattern":"What is **that**? / Who owns **these**?","commonMistakes":["The word it refers back to an identified thing but does not make the same near/far contrast."],"examples":["Point to several books beside you: “**These** books are ours.”","Point to several boxes beside you: “**These** boxes are ours.”"],"skill":"contrast","id":"demonstratives-foundation-3","domain":"reference","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"title":"Referring to ideas and time","explanation":"This and that can refer to an event or whole idea. This week identifies the current week; that week points to a week already identified elsewhere. In conversation, that often responds to something just said.","pattern":"The train was cancelled. **That** was frustrating.","commonMistakes":["Real conversational choices depend on viewpoint. The questions here use explicit physical distance rather than judging subjective emphasis."],"examples":["Point to several books far away beyond the fence: “**Those** books are theirs.”","Point to several boxes far away beyond the fence: “**Those** boxes are theirs.”"],"skill":"application","id":"demonstratives-foundation-4","domain":"reference","referenceIds":["bc-determiners"],"readingVersion":"core-2026-09-v3"},{"domain":"reference","id":"deixis-and-viewpoint","title":"Deixis: here, there, now, then, come and go","explanation":"Deictic expressions depend on the speaker’s or a represented person’s viewpoint. Here and now identify a location and time relative to that viewpoint; this and that can organise a discussion as well as indicate physical distance. Come and go also reflect a chosen centre, which can shift to a listener or a story character.","pattern":"**here / there** · **now / then** · **this / that**","examples":["I’ll **come to your office** tomorrow.","In that letter, **tomorrow** meant the day after it was written."],"commonMistakes":["Quoted language preserves the original viewpoint; a later report may need different time and place words. There is no automatic replacement without context."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**This** seat is free. / **That** seat by the door is taken.","**These books are** mine. / **Those books are** yours.","What is **that**? / Who owns **these**?","The train was cancelled. **That** was frustrating."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["present-simple-be"],"readingReferenceIds":["bc-determiners","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='demonstratives'
